sys_ux_data_broker_transform.script:
function transform(input) {
    // Initialize the result object
    var result = {
        software_requests: []
    };

    // System property name that contains your software request data
    var propertyName = 'sam.implementation.automation';

    // Function to fetch and parse data from system property
    function fetchPropertyData(propName) {
        gs.log("Fetching data from system property: " + propName);

        var propertyValue = gs.getProperty(propName);

        if (propertyValue) {
            gs.log("Successfully retrieved value from property: " + propName);
            try {
                return JSON.parse(propertyValue);
            } catch (e) {
                gs.log("Error parsing JSON from property " + propName + ": " + e.message);
                return [];
            }
        } else {
            gs.log("Property not found or empty: " + propName);
            return [];
        }
    }

    // Get data from system property
    var softwareRequestData = fetchPropertyData(propertyName);

    // Assign the data to the result
    if (softwareRequestData && Array.isArray(softwareRequestData) && softwareRequestData.length > 0) {
        result.software_requests = softwareRequestData;
        gs.log("Successfully processed " + softwareRequestData.length + " software request items");
    } else {
        gs.log("No valid data found in property: " + propertyName);
    }

    gs.log('Final result: ' + JSON.stringify(result, null, 2));
    return result;
}
